new file mode 100644
--- /dev/null
+++ b/crates/core/flags/complete/bash.rs
@@ -0,0 +1,57 @@
+use crate::flags::defs::AllFlags;
+use crate::flags::complete::CompleteFlags;
+
+pub fn complete(flags: &CompleteFlags) -> String {
+    let mut completions = Vec::new();
+    
+    // Add flag completions
+    for flag in AllFlags::iter() {
+        if let Some(long) = flag.long() {
+            completions.push(format!("--{}", long));
+        }
+        if let Some(short) = flag.short() {
+            completions.push(format!("-{}", short));
+        }
+    }
+    
+    // Add file completions for arguments that take paths
+    completions.push("-o".to_string());
+    completions.push("--output".to_string());
+    
+    completions.sort();
+    completions.dedup();
+    
+    let mut output = String::new();
+    output.push_str("complete -o default -c rg\n");
+    
+    for completion in completions {
+        output.push_str(&format!("complete -o default -c rg -l {} -a '{}'\n", 
+            completion, completion));
+    }
+    
+    output
+}
+
+#[cfg(test)]
+mod tests {
+    use super::*;
+    
+    #[test]
+    fn test_complete_generates_output() {
+        let flags = CompleteFlags::default();
+        let output = complete(&flags);
+        assert!(!output.is_empty());
+        assert!(output.contains("complete -c rg"));
+    }
+}

diff --git a/crates/cli/src/hostname.rs b/crates/cli/src/hostname.rs
new file mode 100644
--- /dev/null
+++ b/crates/cli/src/hostname.rs
@@ -0,0 +1,106 @@
+use std::env;
+use std::ffi::OsString;
+use std::io;
+use std::process;
+
+use bstr::ByteSlice;
+
+use crate::args::Config;
+
+/// Returns the hostname of the machine, if it can be determined.
+///
+/// If the `--hostname-bin` flag was provided, then the hostname is obtained
+/// by executing the given program and using its stdout as the hostname.
+/// Otherwise, the hostname is obtained via the standard `gethostname` system
+/// call.
+pub fn gethostname(config: &Config) -> Option<Vec<u8>> {
+    if let Some(ref bin) = config.hostname_bin {
+        gethostname_bin(bin)
+    } else {
+        gethostname_sys()
+    }
+}
+
+fn gethostname_bin(bin: &OsString) -> Option<Vec<u8>> {
+    let output = process::Command::new(bin)
+        .output()
+        .ok()?;
+    if !output.status.success() {
+        return None;
+    }
+    let hostname = output.stdout.trim();
+    if hostname.is_empty() {
+        return None;
+    }
+    Some(hostname.to_vec())
+}
+
+fn gethostname_sys() -> Option<Vec<u8>> {
+    let mut buf = vec![0u8; 256];
+    let len = loop {
+        let res = unsafe {
+            libc::gethostname(buf.as_mut_ptr() as *mut libc::c_char, buf.len())
+        };
+        if res == 0 {
+            break libc::strlen(buf.as_ptr() as *const libc::c_char);
+        }
+        let err = io::Error::last_os_error();
+        if err.kind() != io::ErrorKind::Nametoolong {
+            return None;
+        }
+        // Grow the buffer and try again.
+        let new_len = buf.len().checked_mul(2)?;
+        buf.resize(new_len, 0);
+    };
+    buf.truncate(len);
+    Some(buf)
+}
+
+#[cfg(test)]
+mod tests {
+    use super::*;
+
+    #[test]
+    fn test_gethostname_sys() {
+        let hostname = gethostname_sys();
+        assert!(hostname.is_some());
+        let hostname = hostname.unwrap();
+        assert!(!hostname.is_empty());
+        // Hostnames should be valid UTF-8 (or at least ASCII)
+        assert!(hostname.is_ascii());
+    }
+}

