+use std::fs::File;
+use std::io;
+use std::path::Path;
+
+#[cfg(unix)]
+use std::os::unix::fs::MetadataExt;
+
+#[cfg(windows)]
+use winapi::um::fileapi::GetFileInformationByHandle;
+#[cfg(windows)]
+use winapi::um::fileapi::BY_HANDLE_FILE_INFORMATION;
+#[cfg(windows)]
+use std::os::windows::io::AsRawHandle;
+
+#[cfg(unix)]
+fn get_file_id(file: &File) -> io::Result<(u64, u64)> {
+    let metadata = file.metadata()?;
+    Ok((metadata.dev(), metadata.ino()))
+}
+
+#[cfg(windows)]
+fn get_file_id(file: &File) -> io::Result<(u64, u64)> {
+    let mut info = BY_HANDLE_FILE_INFORMATION {
+        dwFileAttributes: 0,
+        ftCreationTime: winapi::um::minwinbase::FILETIME {
+            dwLowDateTime: 0,
+            dwHighDateTime: 0,
+        },
+        ftLastAccessTime: winapi::um::minwinbase::FILETIME {
+            dwLowDateTime: 0,
+            dwHighDateTime: 0,
+        },
+        ftLastWriteTime: winapi::um::minwinbase::FILETIME {
+            dwLowDateTime: 0,
+            dwHighDateTime: 0,
+        },
+        dwVolumeSerialNumber: 0,
+        nFileSizeHigh: 0,
+        nFileSizeLow: 0,
+        nNumberOfLinks: 0,
+        nFileIndexHigh: 0,
+        nFileIndexLow: 0,
+    };
+
+    let result = unsafe {
+        GetFileInformationByHandle(file.as_raw_handle() as *mut _, &mut info)
+    };
+
+    if result == 0 {
+        return Err(io::Error::last_os_error());
+    }
+
+    let file_index = ((info.nFileIndexHigh as u64) << 32) | (info.nFileIndexLow as u64);
+    let volume_serial = info.dwVolumeSerialNumber as u64;
+    Ok((volume_serial, file_index))
+}
+
+pub fn files_are_same(path1: &Path, path2: &Path) -> io::Result<bool> {
+    if path1 == path2 {
+        return Ok(true);
+    }
+
+    // Try to canonicalize both paths
+    let canonical1 = path1.canonicalize().ok();
+    let canonical2 = path2.canonicalize().ok();
+
+    if let (Some(c1), Some(c2)) = (&canonical1, &canonical2) {
+        if c1 == c2 {
+            return Ok(true);
+        }
+    }
+
+    // If canonicalization failed or paths differ, open files and compare IDs
+    let file1 = File::open(path1)?;
+    let file2 = File::open(path2)?;
+
+    let id1 = get_file_id(&file1)?;
+    let id2 = get_file_id(&file2)?;
+
+    Ok(id1 == id2)
+}
+
+#[cfg(test)]
+mod tests {
+    use super::*;
+    use std::io::Write;
+    use tempfile::tempdir;
+
+    #[test]
+    fn test_same_file() {
+        let dir = tempdir().unwrap();
+        let file_path = dir.path().join("test.txt");
+        
+        {
+            let mut file = File::create(&file_path).unwrap();
+            file.write_all(b"test content").unwrap();
+        }
+
+        assert!(files_are_same(&file_path, &file_path).unwrap());
+    }
+
+    #[test]
+    fn test_different_files() {
+        let dir = tempdir().unwrap();
+        let file1 = dir.path().join("test1.txt");
+        let file2 = dir.path().join("test2.txt");
+        
+        {
+            let mut f1 = File::create(&file1).unwrap();
+            f1.write_all(b"content 1").unwrap();
+        }
+        {
+            let mut f2 = File::create(&file2).unwrap();
+            f2.write_all(b"content 2").unwrap();
+        }
+
+        assert!(!files_are_same(&file1, &file2).unwrap());
+    }
+}
