+/// Check if an expression contains the $in variable
+fn contains_in_variable(working_set: &StateWorkingSet, expr: &Expression) -> bool {
+    match &expr.expr {
+        Expr::Var(id) => *id == IN_VARIABLE_ID,
+        Expr::Block(block) => {
+            for pipeline in &block.pipelines {
+                for element in &pipeline.elements {
+                    if contains_in_variable(working_set, &element.expr) {
+                        return true;
+                    }
+                }
+            }
+            false
+        }
+        Expr::Collect(inner) => contains_in_variable(working_set, inner),
+        Expr::List(items) => items.iter().any(|item| contains_in_variable(working_set, item)),
+        Expr::Record(entries) => entries
+            .iter()
+            .any(|(_, value)| contains_in_variable(working_set, value)),
+        _ => false,
+    }
