+/// Removes all whitespace characters that are outside of double quotes.
+/// This is used to implement the `--raw` flag for `to json`.
+fn remove_whitespace_outside_quotes(input: &str) -> String {
+    let mut result = String::with_capacity(input.len());
+    let mut in_quotes = false;
+    let mut chars = input.chars().peekable();
+
+    while let Some(c) = chars.next() {
+        match c {
+            '"' => {
+                in_quotes = !in_quotes;
+                result.push(c);
+            }
+            c if !in_quotes && c.is_ascii_whitespace() => {
+                // Skip whitespace outside of quotes
+                continue;
+            }
+            _ => {
+                result.push(c);
+            }
+        }
+    }
+
+    result
+}
