@@ -0,0 +1,50 @@
+use crate::ast::RecordEntry;
+use crate::Type;
+
+impl Type {
+    /// Check if a record type is compatible with another record type
+    /// A record without specific fields (just `record`) is compatible with any record type
+    pub fn is_record_compatible_with(&self, expected: &Type) -> bool {
+        match (self, expected) {
+            // record<> is compatible with any record type
+            (Type::Record(None), Type::Record(_)) => true,
+            // record<fields> is compatible with record<fields> if all fields match
+            (Type::Record(Some(self_fields)), Type::Record(Some(expected_fields))) => {
+                self_fields.iter().all(|(name, ty)| {
+                    expected_fields
+                        .iter()
+                        .any(|(exp_name, exp_ty)| name == exp_name && ty.is_subtype_of(exp_ty))
+                })
+            }
+            _ => false,
+        }
+    }
+}

