+++ b/crates/nu-parser/src/span_array.rs
@@ -0,0 +1,47 @@
+//! Safe span array operations
+//!
+//! This module provides checked access to span arrays to prevent
+//! index out of bounds panics. Instead of using direct indexing,
+//! use the safe getter methods which return Option<Span>.
+
+use crate::Span;
+
+/// A non-empty array of spans that guarantees at least one element.
+/// This type is useful for parser operations that always expect
+/// at least one span (e.g., parsing expressions that must have a span).
+#[derive(Debug, Clone)]
+pub struct NonEmptySpanArray {
+    spans: Vec<Span>,
+}
+
+impl NonEmptySpanArray {
+    /// Create a new NonEmptySpanArray from a slice of spans.
+    /// Returns None if the slice is empty.
+    pub fn new(spans: &[Span]) -> Option<Self> {
+        if spans.is_empty() {
+            None
+        } else {
+            Some(Self {
+                spans: spans.to_vec(),
+            })
+        }
+    }
+
+    /// Create from a single span
+    pub fn from_span(span: Span) -> Self {
+        Self {
+            spans: vec![span],
+        }
+    }
+
+    /// Get a span by index, returning None if out of bounds
+    pub fn get(&self, index: usize) -> Option<&Span> {
+        self.spans.get(index)
+    }
+
+    /// Get the first span (always exists by construction)
+    pub fn first(&self) -> &Span {
+        // This is safe because we guarantee non-empty on construction
+        unsafe { self.spans.get_unchecked(0) }
+    }
+
+    /// Get the last span (always exists by construction)
+    pub fn last(&self) -> &Span {
+        // This is safe because we guarantee non-empty on construction
+        unsafe { self.spans.get_unchecked(self.spans.len() - 1) }
+    }
+
+    /// Iterate over all spans
+    pub fn iter(&self) -> impl Iterator<Item = &Span> {
+        self.spans.iter()
+    }
+}

