diff --git a/tracing-subscriber/src/layer/context.rs b/tracing-subscriber/src/layer/context.rs
new file mode 100644
index 0000000..1234567
--- /dev/null
+++ b/tracing-subscriber/src/layer/context.rs
@@ -0,0 +1,1075 @@
+//! The `Context` type, a wrapper around `tracing_core::span::Context`.
+
+use crate::layer::{FilterId, Layered, PerLayerFilter, Layer};
+use crate::registry::{Registry, Extensions};
+use std::fmt;
+use std::sync::Arc;
+use tracing_core::{
+    field::Field,
+    span::{Attributes, Id, SpanRef},
+    Event, Metadata, Subscriber,
+};
+
+/// A collection of added `Layer`s.
+#[derive(Debug)]
+pub struct Context<'a, S> {
+    /// The wrapped subscriber, with added `Layer`s.
+    subscriber: &'a S,
+
+    /// The filter map for per-layer filtering.
+    /// This is `None` if per-layer filtering is not enabled.
+    filter_map: Option<PerLayerFilter>,
+}
+
+impl<'a, S> Context<'a, S> {
+    /// Wraps the provided subscriber with the added `Layer`s.
+    #[inline]
+    pub(super) fn new(subscriber: &'a S, filter_map: Option<PerLayerFilter>) -> Self {
+        Self {
+            subscriber,
+            filter_map,
+        }
+    }
+
+    /// Returns whether the given `Layer` has enabled the given `Id`.
+    #[inline]
+    pub fn layer_enabled(&self, id: &Id) -> bool {
+        match self.filter_map {
+            Some(ref filter_map) => !filter_map.is_enabled(id),
+            None => true,
+        }
+    }
+}
+
+impl<'a, S: Subscriber> Context<'a, S> {
+    /// Returns the `Layer` for the innermost layer of this subscriber that
+    /// implements `LookupSpan`.
+    #[inline]
+    pub fn lookup_latest_layer(&self) -> Option<SpanRef<'_, S>> {
+        self.subscriber.span(id)
+    }
+
+    /// Returns whether this subscriber has any spans.
+    #[inline]
+    pub fn has_spans(&self) -> bool {
+        self.subscriber.enabled(&tracing_core::span::Attributes::new(
+            tracing_core::span::Id::from_u64(0),
+            None,
+            &tracing_core::field::FieldSet::new(&[], tracing_core::callsite::Identifier(&())),
+            tracing_core::span::Kind::Enter,
+        )) || self.subscriber.max_level_hint() != Some(tracing_core::Level::TRACE)
+    }
+
+    /// Returns a reference to the `Extensions` of `self`.
+    ///
+    /// **Note**: This is the extensions of the *subscriber*, not the
+    /// extensions of the `Context`.
+    ///
+    /// If the `Registry` does not store any extensions, this method will
+    /// return `None`.
+    #[inline]
+    pub fn extensions(&self) -> Option<&Extensions> {
+        self.subscriber.extensions()
+    }
+
+    /// Returns a mutable reference to the `Extensions` of `self`.
+    ///
+    /// **Note**: This is the extensions of the *subscriber*, not the
+    /// extensions of the `Context`.
+    ///
+    /// If the `Registry` does not store any extensions, this method will
+    /// return `None`.
+    #[inline]
+    pub fn extensions_mut(&mut self) -> Option<&mut Extensions> {
+        self.subscriber.extensions_mut()
+    }
+
+    /// Records that the given `Layer` disabled the given `Id`.
+    #[inline]
+    pub fn record_layer_disabled(&mut self, id: &Id, layer: FilterId) {
+        if let Some(ref mut filter_map) = self.filter_map {
+            filter_map.record_disabled(id, layer);
+        }
+    }
+
+    /// Returns the filter map for per-layer filtering.
+    #[inline]
+    pub fn filter_map(&self) -> Option<&PerLayerFilter> {
+        self.filter_map.as_ref()
+    }
+}
+
+impl<'a, S> Context<'a, Layered<S>>
+where
+    S: Subscriber,
+{
+    /// Returns an iterator over all spans in the current context, starting
+    /// with the most recently entered span.
+    #[inline]
+    pub fn event_scope(&self) -> Option<Iter<'a, S>> {
+        self.event_span().map(|span| Iter::new(span))
+    }
+
+    /// Returns the current span.
+    #[inline]
+    pub fn event_span(&self) -> Option<SpanRef<'a, Layered<S>>> {
+        self.subscriber.event_span()
+    }
+}
+
+impl<'a, S> Context<'a, Layered<S>>
+where
+    S: Subscriber + 'static,
+{
+    /// Returns a reference to the subscriber by reference.
+    #[inline]
+    pub fn subscriber(&self) -> &S {
+        self.subscriber.subscriber()
+    }
+}
+
+/// Iterator over spans, from the most recent to the oldest.
+#[derive(Debug)]
+pub struct Iter<'a, S> {
+    inner: Option<SpanRef<'a, S>>,
+}
+
+impl<'a, S: Subscriber> Iter<'a, S> {
