+//! Utilities for working with span fields.
+
+use tracing_core::field::{Field, Visit};
+use std::fmt;
+
+/// A `Visit`or that records the fields and values that have been recorded.
+#[derive(Default)]
+pub struct RecordedFields {
+    /// The set of fields that have been recorded.
+    pub fields: Vec<String>,
+}
+
+impl Visit for RecordedFields {
+    fn record_str(&mut self, field: &Field, value: &str) {
+        self.fields.push(format!("{}={}", field.name(), value));
+    }
+
+    fn record_u64(&mut self, field: &Field, value: u64) {
+        self.fields.push(format!("{}={}", field.name(), value));
+    }
+
+    fn record_i64(&mut self, field: &Field, value: i64) {
+        self.fields.push(format!("{}={}", field.name(), value));
+    }
+
+    fn record_bool(&mut self, field: &Field, value: bool) {
+        self.fields.push(format!("{}={}", field.name(), value));
+    }
+
+    fn record_debug(&mut self, field: &Field, value: &fmt::Debug) {
+        self.fields.push(format!("{}={:?}", field.name(), value));
+    }
+}
+
+/// A `Visit`or that records the fields that have been recorded, without values.
+#[derive(Default)]
+pub struct RecordedFieldNames {
+    /// The set of field names that have been recorded.
+    pub fields: Vec<String>,
+}
+
+impl Visit for RecordedFieldNames {
+    fn record_str(&mut self, field: &Field, _value: &str) {
+        self.fields.push(field.name().to_string());
+    }
+
+    fn record_u64(&mut self, field: &Field, _value: u64) {
+        self.fields.push(field.name().to_string());
+    }
+
+    fn record_i64(&mut self, field: &Field, _value: i64) {
+        self.fields.push(field.name().to_string());
+    }
+
+    fn record_bool(&mut self, field: &Field, _value: bool) {
+        self.fields.push(field.name().to_string());
+    }
+
+    fn record_debug(&mut self, field: &Field, _value: &fmt::Debug) {
+        self.fields.push(field.name().to_string());
+    }
+}
