+//! Per-layer filter implementations.
+
+use crate::layer::Filter;
+use std::fmt;
+use tracing_core::{span::Id, Metadata, Subscriber};
+
+/// A `Layer` that filters events based on a `LevelFilter`.
+#[derive(Clone)]
+pub struct LevelFilter {
+    level: crate::filter::LevelFilter,
+}
+
+impl LevelFilter {
+    /// Returns a new `LevelFilter` that will only enable spans/events at
+    /// the specified level.
+    #[inline]
+    pub fn new(level: crate::filter::LevelFilter) -> Self {
+        Self { level }
+    }
+}
+
+impl<S: Subscriber> Filter<S> for LevelFilter {
+    #[inline]
+    fn enabled(&self, meta: &Metadata<'_>, _: &tracing_core::layer::Context<'_, S>) -> bool {
+        // The `LevelFilter` is a `u32`, where the most significant byte
+        // represents the level, and the least significant byte represents
+        // whether or not that level is enabled. Since `Metadata::level`
+        // returns the level as a `u32`, we can compare them directly.
+        let level = *meta.level() as u32;
+        let max_level = self.level.into_u32();
+        level <= max_level
+    }
+}
+
+impl fmt::Debug for LevelFilter {
+    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
+        f.debug_tuple("LevelFilter")
+            .field(&self.level)
+            .finish()
+    }
+}
+
+/// A function that can be used as a per-layer filter's `enabled` method.
+pub type FilterFn = fn(&Metadata<'_>, &tracing_core::layer::Context<'_, impl Subscriber>) -> bool;
+
+/// A `Filter` implementation that wraps a function or closure.
+///
+/// This is similar to how `tracing_subscriber::filter::LevelFilter` wraps
+/// a `LevelFilter`, but allows the user to provide an arbitrary function
+/// or closure.
+#[derive(Clone)]
+pub struct DynFilterFn<F = FilterFn> {
+    filter_fn: F,
+}
+
+impl<F> DynFilterFn<F> {
+    /// Returns a new `DynFilterFn` that wraps the provided filter function.
+    #[inline]
+    pub fn new(filter_fn: F) -> Self {
+        Self { filter_fn }
+    }
+}
+
+impl<F, S> Filter<S> for DynFilterFn<F>
+where
+    F: Fn(&Metadata<'_>, &tracing_core::layer::Context<'_, S>) -> bool + Clone,
+    S: Subscriber,
+{
+    #[inline]
+    fn enabled(&self, meta: &Metadata<'_>, ctx: &tracing_core::layer::Context<'_, S>) -> bool {
+        (self.filter_fn)(meta, ctx)
+    }
+}
+
+impl<F> fmt::Debug for DynFilterFn<F> {
+    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
+        f.debug_struct("DynFilterFn")
+            .field("filter_fn", &"...")
+            .finish()
+    }
+}
