diff --git a/tests/test_unrestricted.rs b/tests/test_unrestricted.rs
new file mode 100644
index 0000000..1234567
--- /dev/null
+++ b/tests/test_unrestricted.rs
@@ -0,0 +1,50 @@
+use std::fs::{self, File};
+use std::io::Write;
+use std::process::Command;
+use tempfile::TempDir;
+
+fn executable_path() -> &'static str {
+    env!("CARGO_BIN_EXE_fd")
+}
+
+#[test]
+fn unrestricted_is_idempotent() {
+    // Test that multiple -u flags produce the same result as a single -u
+    let temp_dir = TempDir::new().unwrap();
+    File::create(temp_dir.path().join(".hidden")).unwrap();
+
+    // Single -u
+    let output_single = Command::new(executable_path())
+        .current_dir(&temp_dir)
+        .arg("hidden")
+        .arg("-u")
+        .output()
+        .unwrap();
+
+    // Double -uu
+    let output_double = Command::new(executable_path())
+        .current_dir(&temp_dir)
+        .arg("hidden")
+        .arg("-uu")
+        .output()
+        .unwrap();
+
+    // Triple -uuu
+    let output_triple = Command::new(executable_path())
+        .current_dir(&temp_dir)
+        .arg("hidden")
+        .arg("-uuu")
+        .output()
+        .unwrap();
+
+    // All should produce the same output
+    assert_eq!(output_single.stdout, output_double.stdout);
+    assert_eq!(output_double.stdout, output_triple.stdout);
+}
+
+#[test]
+fn unrestricted_flag_equivalent_to_IH() {
+    let temp_dir = TempDir::new().unwrap();
+    File::create(temp_dir.path().join(".hidden")).unwrap();
+
+    // -u should be equivalent to -IH
+    let output_u = Command::new(executable_path())
+        .current_dir(&temp_dir)
+        .arg("hidden")
+        .arg("-u")
+        .output()
+        .unwrap();
+
+    let output_IH = Command::new(executable_path())
+        .current_dir(&temp_dir)
+        .arg("hidden")
+        .arg("-IH")
+        .output()
+        .unwrap();
+
+    assert_eq!(output_u.stdout, output_IH.stdout);
+}

