@@ -0,0 +1,45 @@
+// Test for issue #4520: `requires` is bypassed when using `conflicts_with` a certain way
+
+#[test]
+fn test_requires_not_bypassed_by_conflicts() {
+    // This test demonstrates the bug where `requires` can be bypassed
+    // when using `conflicts_with` in a certain way
+    use clap::{Arg, Command};
+    
+    let cmd = Command::new("test")
+        .arg(
+            Arg::new("destroy")
+                .long("destroy")
+                .required(true)
+                .conflicts_with("keep")
+        )
+        .arg(
+            Arg::new("keep")
+                .long("keep")
+                .required(true)
+                .conflicts_with("destroy")
+        );
+    
+    // Both --destroy and --keep are required, but they conflict with each other.
+    // Providing neither should fail.
+    let result = cmd.clone().try_get_matches_from(vec!["test"]);
+    assert!(result.is_err(), "Should fail when required conflicting args are missing");
+    
+    // Providing just --destroy should succeed (it's required and valid)
+    let result = cmd.clone().try_get_matches_from(vec!["test", "--destroy"]);
+    assert!(result.is_ok(), "Should succeed with just --destroy");
+    
+    // Providing just --keep should succeed (it's required and valid)
+    let result = cmd.try_get_matches_from(vec!["test", "--keep"]);
+    assert!(result.is_ok(), "Should succeed with just --keep");
+}
+
+#[test]
+fn test_requires_not_bypassed_by_conflicts_2() {
+    use clap::{Arg, Command};
+    
+    let cmd = Command::new("test")
+        .arg(
+            Arg::new("a")
+                .long("a")
+                .required(true)
+        )
+        .arg(
+            Arg::new("b")
+                .long("b")
+                .requires("c")
+        )
+        .arg(
+            Arg::new("c")
+                .long("c")
+                .conflicts_with("a")
+        );
+    
+    // --b requires --c, but --c conflicts with --a
+    // This should fail because --a is required and --c conflicts with it
+    let result = cmd.try_get_matches_from(vec!["test", "--a", "--b"]);
+    assert!(result.is_err(), "Should fail because --b requires --c which conflicts with --a");
+}
