+// Find example
+// This example demonstrates how to iterate over argument IDs present in the matches.
+
+use clap::{Arg, Command};
+
+pub fn main() {
+    let cmd = Command::new("find")
+        .arg(Arg::new("path").long("path").takes_value(true))
+        .arg(Arg::new("name").long("name").takes_value(true))
+        .arg(Arg::new("type").long("type").takes_value(true))
+        .arg(Arg::new("verbose").short('v').multiple_occurrences(true));
+
+    let matches = cmd.try_get_matches_from(vec!["find", "--path", "/tmp", "-vv"]).unwrap();
+
+    // Iterate over all argument IDs present in the matches
+    for id in matches.ids() {
+        println!("Argument present: {}", id.as_str());
+    }
+}
