diff --git a/src/build/arg/id.rs b/src/build/arg/id.rs
new file mode 100644
--- /dev/null
+++ b/src/build/arg/id.rs
@@ -0,0 +1,68 @@
+use std::fmt::{self, Display};
+use std::hash::Hash;
+
+/// A unique identifier for an argument or group.
///
/// This identifier can be used to programmatically act on arguments
+/// and groups within the command-line parsing context.
+#[derive(Debug, Clone, PartialEq, Eq, Hash)]
+pub struct Id(String);
+
+impl Id {
+    /// Create a new identifier from a string.
+    pub(crate) fn new<S: Into<String>>(id: S) -> Self {
+        Id(id.into())
+    }
+
+    /// Get the identifier as a string slice.
+    pub fn as_str(&self) -> &str {
+        &self.0
+    }
+}
+
+impl Display for Id {
+    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
+        write!(f, "{}", self.0)
+    }
+}
+
+impl From<&str> for Id {
+    fn from(s: &str) -> Self {
+        Id::new(s)
+    }
+}
+
+impl From<String> for Id {
+    fn from(s: String) -> Self {
+        Id::new(s)
+    }
+}
