+++ b/src/build/arg/action.rs
@@ -0,0 +1,50 @@
+/// The action to take when parsing an argument.
+///
+/// See [`Arg::action`](crate::Arg::action).
+#[derive(Copy, Clone, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
+pub enum Action {
+    /// Store the value. This is the default action.
+    Store,
+    /// Store the value, ignoring all duplicates.
+    Append,
+    /// Set the value to `true`.
+    SetTrue,
+    /// Set the value to `false`.
+    SetFalse,
+    /// Count the number of occurrences.
+    Count,
+}
+
+impl Default for Action {
+    fn default() -> Self {
+        Self::Store
+    }
+}
+
+impl Action {
+    /// Returns `true` if this action stores multiple values.
+    pub fn is_append(&self) -> bool {
+        matches!(self, Self::Append)
+    }
+
+    /// Returns `true` if this action stores a value.
+    pub fn is_store(&self) -> bool {
+        matches!(self, Self::Store | Self::Append)
+    }
+
+    /// Returns `true` if this action sets a boolean flag.
+    pub fn is_set(&self) -> bool {
+        matches!(self, Self::SetTrue | Self::SetFalse)
+    }
+
+    /// Returns `true` if this action counts occurrences.
+    pub fn is_count(&self) -> bool {
+        matches!(self, Self::Count)
+    }
+}

