--- /dev/null
+++ b/src/error/context.rs
@@ -0,0 +1,127 @@
+//! Error context and building blocks for custom error formatting.
+//!
+//! This module exposes the internal components used to build error messages,
+//! allowing users to construct their own error formatting if desired.
+
+use crate::builder::Command;
+use crate::output::fmt::Format;
+use crate::output::usage::Usage;
+use crate::output::help::Help;
+use crate::parser::Parser;
+use crate::output::tab::Tab;
+
+/// Context for error formatting
+///
+/// This struct holds all the information needed to format an error message.
+/// It can be used to build custom error formats.
+#[derive(Debug, Clone)]
+pub struct Context<'help, 'cmd> {
+    /// The command that generated the error
+    pub command: &'cmd Command<'cmd>,
+    /// The usage string
+    pub usage: Option<Usage<'help, 'cmd>>,
+    /// The help message (if applicable)
+    pub help: Option<Help<'help>>,
+    /// The error kind
+    pub kind: ErrorKind,
+    /// Whether to use color
+    pub color: Color,
+}
+
+impl<'help, 'cmd> Context<'help, 'cmd> {
+    /// Create a new error context
+    pub fn new(
+        command: &'cmd Command<'cmd>,
+        kind: ErrorKind,
+    ) -> Self {
+        Self {
+            command,
+            usage: None,
+            help: None,
+            kind,
+            color: Color::Auto,
+        }
+    }
+
+    /// Set the usage string
+    pub fn with_usage(mut self, usage: Usage<'help, 'cmd>) -> Self {
+        self.usage = Some(usage);
+        self
+    }
+
+    /// Set the help message
+    pub fn with_help(mut self, help: Help<'help>) -> Self {
+        self.help = Some(help);
+        self
+    }
+
+    /// Set the color mode
+    pub fn with_color(mut self, color: Color) -> Self {
+        self.color = color;
+        self
+    }
+
+    /// Build the formatted error message
+    pub fn formatted(&self) -> String {
+        let mut output = String::new();
+
+        // Format the error message
+        output.push_str(&self.kind.to_string());
+        output.push_str(": ");
+
+        // Add help if present
+        if let Some(help) = &self.help {
+            output.push_str(&help.to_string());
+            output.push('\n');
+        }
+
+        // Add usage if present
+        if let Some(usage) = &self.usage {
+            output.push_str(&usage.to_string());
+        }
+
+        output
+    }
+}
+
+/// Color control for error output
+#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
+pub enum Color {
+    /// Automatically detect color support
+    #[default]
+    Auto,
+    /// Always use colors
+    Always,
+    /// Never use colors
+    Never,
+}
+
+impl Color {
+    pub(crate) fn should_colorize(&self) -> bool {
+        match self {
+            Color::Auto => atty::is(atty::Stream::Stderr),
+            Color::Always => true,
+            Color::Never => false,
+        }
+    }
+}
+
+/// Error kind enumeration
+#[derive(Debug, Clone, Copy, PartialEq, Eq)]
+pub enum ErrorKind {
+    /// Display help message
+    DisplayHelp,
+    /// Display version information
+    DisplayVersion,
+    /// Argument parsing failed
+    InvalidArgument,
+    /// Missing required argument
+    MissingRequiredArgument,
+    /// Too many arguments provided
+    TooManyArguments,
+    /// Invalid value provided
+    InvalidValue,
+    /// Unexpected argument
+    UnexpectedArgument,
+    /// Ambiguous argument
+    AmbiguousArgument,
+    /// Invalid subcommand
+    InvalidSubcommand,
+    /// Missing subcommand
+    MissingSubcommand,
+    /// IO error occurred
+    Io,
+    /// Format error occurred
+    Format,
+}
+
+impl std::fmt::Display for ErrorKind {
+    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
+        match self {
+            ErrorKind::DisplayHelp => write!(f, "help"),
+            ErrorKind::DisplayVersion => write!(f, "version"),
+            ErrorKind::InvalidArgument => write!(f, "invalid argument"),
+            ErrorKind::MissingRequiredArgument => write!(f, "missing required argument"),
+            ErrorKind::TooManyArguments => write!(f, "too many arguments"),
+            ErrorKind::InvalidValue => write!(f, "invalid value"),
+            ErrorKind::UnexpectedArgument => write!(f, "unexpected argument"),
+            ErrorKind::AmbiguousArgument => write!(f, "ambiguous argument"),
+            ErrorKind::InvalidSubcommand => write!(f, "invalid subcommand"),
+            ErrorKind::MissingSubcommand => write!(f, "missing subcommand"),
+            ErrorKind::Io => write!(f, "io error"),
+            ErrorKind::Format => write!(f, "format error"),
+        }
+    }
+}
+
+impl Default for ErrorKind {
+    fn default() -> Self {
+        ErrorKind::InvalidArgument
+    }
+}
