+#[test]
+fn test_vec_multiple_occurrences() {
+    // Test that Vec<_> infers multiple_occurrences but not required
+    #[derive(Clap, Debug)]
+    struct Args {
+        #[clap(short)]
+        values: Vec<String>,
+    }
+    
+    // Should not fail when no values are provided
+    let result = Args::try_parse_from(&["test"]);
+    assert!(result.is_ok());
+    
+    // Should accept multiple occurrences
+    let result = Args::try_parse_from(&["test", "-v", "a", "-v", "b"]);
