+    assert_eq!(args.values, vec!["a".to_string(), "b".to_string()]);
+    
+    // Should NOT accept space-separated values (multiple values, not multiple occurrences)
+    let result = Args::try_parse_from(&["test", "-v", "a", "b"]);
+    // This should fail because we want multiple_occurrences, not multiple_values
+    assert!(result.is_err() || result.unwrap().values != vec!["a".to_string(), "b".to_string()]);
+}

