diff --git a/tests/default_value_t.rs b/tests/default_value_t.rs
new file mode 100644
index 0000000..1234567
--- /dev/null
+++ b/tests/default_value_t.rs
@@ -0,0 +1,62 @@
+use clap::{AppSettings, Arg, Clap};
+
+/// Test using default_value_t with T::default()
+#[derive(Clap, Debug, PartialEq)]
+pub struct Opt1 {
+    #[clap(short, long, default_value_t)]
+    pub port: u16,
+}
+
+/// Test using default_value_t with an expression
+#[derive(Clap, Debug, PartialEq)]
+pub struct Opt2 {
+    #[clap(short, long, default_value_t = 8080)]
+    pub port: u16,
+}
+
+/// Test using default_value_t with a more complex expression
+#[derive(Clap, Debug, PartialEq)]
+pub struct Opt3 {
+    #[clap(short, long, default_value_t = String::from("hello"))]
+    pub name: String,
+}
+
+/// Test that default_value_t and default_value work together
+#[derive(Clap, Debug, PartialEq)]
+pub struct Opt4 {
+    #[clap(short, long, default_value = "custom", default_value_t = "default")]
+    pub value: String,
+}
+
+fn assert_eq<T: ::std::fmt::Debug + PartialEq + ::std::default::Default>(left: T, right: T) {
+    assert_eq!(left, right);
+}
+
+#[test]
+fn test_default_value_t_default() {
+    let opt = Opt1::parse_from(&["test"]);
+    assert_eq!(opt.port, <u16 as ::std::default::Default>::default());
+    assert_eq!(opt.port, 0);
+}
+
+#[test]
+fn test_default_value_t_expr() {
+    let opt = Opt2::parse_from(&["test"]);
+    assert_eq!(opt.port, 8080);
+}
+
+#[test]
+fn test_default_value_t_string_expr() {
+    let opt = Opt3::parse_from(&["test"]);
+    assert_eq!(opt.name, String::from("hello"));
+}
+
+#[test]
+fn test_default_value_t_with_default_value() {
+    // When both are specified, default_value_t provides the actual value
+    // and default_value provides the string representation
+    let opt = Opt4::parse_from(&["test"]);
+    assert_eq!(opt.value, String::from("default"));
+}
+
+#[test]
+fn test_default_value_t_explicit_override() {
+    let opt = Opt1::parse_from(&["test", "-p", "3000"]);
+    assert_eq!(opt.port, 3000);
+}
+
+#[test]
+fn test_default_value_t_help() {
+    let app = Opt2::command();
+    let help = app.render_help().to_string();
+    // The default value should appear in help
+    assert!(help.contains("[default: 8080]"));
+}

