@@ -0,0 +1,54 @@
+#ifndef SIMDJSON_TEST_ONDEMAND_COUNT_FIELDS_H
+#define SIMDJSON_TEST_ONDEMAND_COUNT_FIELDS_H
+
+#include "simdjson.h"
+
+namespace simdjson {
+
+bool test_count_fields() {
+  std::cout << "Testing count_fields()..." << std::endl;
+
+  ondemand::parser parser;
+
+  // Test empty object
+  {
+    auto json = "{}"_padded;
+    ondemand::document doc = parser.iterate(json);
+    ondemand::object obj = doc.get_object();
+    ASSERT_EQUAL( simdjson::get_error(obj.count_fields()), size_t(0) );
+  }
+
+  // Test object with one field
+  {
+    auto json = "{\"a\": 1}"_padded;
+    ondemand::document doc = parser.iterate(json);
+    ondemand::object obj = doc.get_object();
+    ASSERT_EQUAL( simdjson::get_error(obj.count_fields()), size_t(1) );
+  }
+
+  // Test object with multiple fields
+  {
+    auto json = "{\"a\": 1, \"b\": 2, \"c\": 3}"_padded;
+    ondemand::document doc = parser.iterate(json);
+    ondemand::object obj = doc.get_object();
+    ASSERT_EQUAL( simdjson::get_error(obj.count_fields()), size_t(3) );
+  }
+
+  // Test nested object
+  {
+    auto json = "{\"a\": {\"b\": 1, \"c\": 2}}"_padded;
+    ondemand::document doc = parser.iterate(json);
+    ondemand::object obj = doc.get_object();
+    ASSERT_EQUAL( simdjson::get_error(obj.count_fields()), size_t(1) );
+  }
+
+  // Test that iteration works after count_fields()
+  {
+    auto json = "{\"a\": 1, \"b\": 2}"_padded;
+    ondemand::document doc = parser.iterate(json);
+    ondemand::object obj = doc.get_object();
+    ASSERT_EQUAL( simdjson::get_error(obj.count_fields()), size_t(2) );
+    
+    // Should be able to iterate after count_fields()
+    size_t count = 0;
+    for (auto field : obj) {
+      count++;
+    }
+    ASSERT_EQUAL(count, size_t(2));
+  }
+
+  std::cout << "count_fields() tests passed!" << std::endl;
+  return true;
+}
+
+} // namespace simdjson
+
+#endif // SIMDJSON_TEST_ONDEMAND_COUNT_FIELDS_H
