+#ifndef INCLUDE_NLOHMANN_DETAIL_STRING_UTILS_HPP_
+#define INCLUDE_NLOHMANN_DETAIL_STRING_UTILS_HPP_
+
+#include <string>
+#include <utility>
+
+namespace nlohmann
+{
+namespace detail
+{
+/*!
+@brief convert a string value to std::string
+
+This function is used to ensure compatibility with custom string types.
+It converts the given string to std::string for comparison and other operations.
+*/
+template<typename BasicJsonType>
+std::string to_std_string(typename BasicJsonType::string_t&& s)
+{
+    return std::move(s);
+}
+
+/*!
+@brief convert a const string reference to std::string
+
+This overload handles const references for cases where the string
+is not movable.
+*/
+template<typename BasicJsonType>
+std::string to_std_string(const typename BasicJsonType::string_t& s)
+{
+    return s;
+}
+
+/*!
+@brief get a string value as std::string
+
+This function extracts a string value from the JSON and converts it
+to std::string, ensuring compatibility with custom string types.
+*/
+template<typename BasicJsonType>
+std::string get_string(const BasicJsonType& j)
+{
+    return j.template get<std::string>();
+}
+
+} // namespace detail
+} // namespace nlohmann
+
+#endif // INCLUDE_NLOHMANN_DETAIL_STRING_UTILS_HPP_
