+TEST_CASE("Custom allocator for binary output" * doctest::test_suite("regression"))
+{
+    // Test custom allocator with to_bson
+    SECTION("to_bson with custom allocator")
+    {
+        nlohmann::json j = {{"key", "value"}, {"number", 42}};
+        
+        // Use a custom allocator
+        std::vector<char, std::allocator<char>> vec = j.to_bson(std::allocator<char>());
+        CHECK(!vec.empty());
+        
+        // Verify the data can be parsed back
+        auto parsed = nlohmann::json::from_bson(vec);
+        CHECK(parsed == j);
+    }
+
+    // Test custom allocator with to_cbor
+    SECTION("to_cbor with custom allocator")
+    {
+        nlohmann::json j = {{"key", "value"}, {"array", {1, 2, 3}}};
+        
+        std::vector<char, std::allocator<char>> vec = j.to_cbor(std::allocator<char>());
+        CHECK(!vec.empty());
+        
+        auto parsed = nlohmann::json::from_cbor(vec);
+        CHECK(parsed == j);
+    }
+
+    // Test custom allocator with to_msgpack
+    SECTION("to_msgpack with custom allocator")
+    {
+        nlohmann::json j = {{"key", "value"}, {"null", nullptr}};
+        
+        std::vector<char, std::allocator<char>> vec = j.to_msgpack(std::allocator<char>());
+        CHECK(!vec.empty());
+        
+        auto parsed = nlohmann::json::from_msgpack(vec);
+        CHECK(parsed == j);
+    }
+
+    // Test custom allocator with to_ubjson
+    SECTION("to_ubjson with custom allocator")
+    {
+        nlohmann::json j = {{"key", "value"}, {"boolean", true}};
+        
+        std::vector<char, std::allocator<char>> vec = j.to_ubjson(std::allocator<char>());
+        CHECK(!vec.empty());
+        
+        auto parsed = nlohmann::json::from_ubjson(vec);
+        CHECK(parsed == j);
+    }
+
+    // Test with pool allocator
+    SECTION("to_cbor with pool allocator")
+    {
+        nlohmann::json j = {{"test", "data"}, {"values", {1, 2, 3, 4, 5}}};
+        
+        // Using the default allocator should still work
+        auto vec1 = j.to_cbor();
+        CHECK(!vec1.empty());
+        
+        // Using explicit allocator
+        auto vec2 = j.to_cbor(std::allocator<char>());
+        CHECK(!vec2.empty());
+        CHECK(vec1 == vec2);
+    }
+
+    // Test that output adapter with allocator works
+    SECTION("output_vector_adapter with custom allocator")
+    {
+        nlohmann::json j = {{"test", 123}};
+        
+        std::vector<char> output;
+        output.reserve(256);
+        
+        // Create output adapter with custom allocator
+        auto adapter = nlohmann::detail::output_adapter::create(output, std::allocator<char>());
+        
+        nlohmann::detail::binary_writer<decltype(adapter)> writer(adapter);
+        j.write_binary(writer, *adapter);
+        
+        CHECK(!output.empty());
+        
+        auto parsed = nlohmann::json::from_cbor(output);
+        CHECK(parsed == j);
+    }
+}
