+static bool completeness_match(passopt_t* opt, ast_t* ast)
+{
+  ast_t* pattern = ast_child(ast);
+  ast_t* guard = ast_childidx(ast, 1);
+  ast_t* body = ast_childidx(ast, 2);
+  ast_t* else_body = ast_childidx(ast, 3);
+  bool is_exhaustive = false;
