+  {
+    case TK_MATCH:
+    {
+      push_frame(opt, ast);
+
+      ast_t* expr = ast_child(ast);
+
+      if(!pass_expr(opt, expr))
+        return AST_ERROR;
+
+      // Visit each case
+      ast_t* case_item = ast_sibling(expr);
+
+      while(case_item != NULL)
+      {
+        if(!completeness_match(opt, case_item))
+          return AST_ERROR;
+
+        case_item = ast_sibling(case_item);
+      }
+
+      pop_frame(opt);
+      return AST_CONTINUE;
+    }
+
+    case TK_TRY:
+    case TK_WHILE:
+    case TK_REPEAT:
+    case TK_FOR:
+    case TK_WITH:
+    {
+      push_frame(opt, ast);
+      break;
+    }
+
+    case TK_IF:
+    case TK_IFTYPE:
+    {
+      // Check for conditional compilation with else
+      ast_t* then = ast_childidx(ast, 2);
+      ast_t* else_ast = ast_childidx(ast, 3);
+
+      if((else_ast != NULL) && (ast_id(else_ast) != TK_SEQ))
+      {
+        push_frame(opt, ast);
+
+        ast_t* cond = ast_child(ast);
+
+        if(!pass_expr(opt, cond))
+          return AST_ERROR;
+
+        ast_t* then_expr = ast_childidx(ast, 1);
+
+        if(!pass_expr(opt, then_expr))
+          return AST_ERROR;
+
+        if(!pass_expr(opt, then))
+          return AST_ERROR;
+
+        if(!pass_expr(opt, else_ast))
+          return AST_ERROR;
+
+        pop_frame(opt);
+        return AST_CONTINUE;
+      }
+
+      push_frame(opt, ast);
+      break;
+    }
+
+    default:
+      break;
+  }
+
+  return AST_CONTINUE;
+}
+
+ast_result_t completeness(ast_t** astp, passopt_t* options)
+{
+  if(options->frame == NULL)
+    options->frame = ast_from(astp, TK_REFERENCE);
+
+  return ast_visit(astp, completeness_visit, options);
+}

