@@ -0,0 +1,62 @@
+package com.alibaba.fastjson2.serializer;
+
+import com.alibaba.fastjson2.JSONWriter;
+import com.alibaba.fastjson2.writer.ObjectWriter;
+import com.alibaba.fastjson2.writer.ObjectWriterProvider;
+
+import java.io.IOException;
+import java.lang.reflect.Type;
+import java.util.EnumSet;
+
+public class EnumSetCodec implements ObjectCodec {
+
+    @Override
+    public void write(JSONWriter jsonWriter, Object object, Type fieldType, WriterFeature... features) {
+        if (object == null) {
+            jsonWriter.writeNull();
+            return;
+        }
+
+        EnumSet enumSet = (EnumSet) object;
+        Class enumClass = enumSet.elementType;
+
+        // Write type information for proper deserialization
+        jsonWriter.startObject();
+        jsonWriter.writeKey("type");
+        jsonWriter.writeString(enumClass.getName());
+        jsonWriter.writeComma();
+        jsonWriter.writeKey("values");
+
+        jsonWriter.startArray();
+        for (Object item : enumSet) {
+            jsonWriter.writeEnum((Enum) item);
+        }
+        jsonWriter.endArray();
+        jsonWriter.endObject();
+    }
+
+    @Override
+    public void writeTo(JSONWriter writer, Object object, Object fieldContext, Type fieldType, WriterFeature... features) {
+        write(writer, object, fieldType, features);
+    }
+}
