diff --git a/src/test/java/com/fasterxml/jackson/core/number/FloatingPointTypeTest.java b/src/test/java/com/fasterxml/jackson/core/number/FloatingPointTypeTest.java
--- a/src/test/java/com/fasterxml/jackson/core/number/FloatingPointTypeTest.java
+++ b/src/test/java/com/fasterxml/jackson/core/number/FloatingPointTypeTest.java
@@ -0,0 +1,76 @@
+package com.fasterxml.jackson.core.number;
+
+import com.fasterxml.jackson.core.*;
+import com.fasterxml.jackson.core.json.JsonFactory;
+
+/**
+ * Tests for verifying {@link JsonParser#getNumberTypeFP()} functionality.
+ */
+public class FloatingPointTypeTest extends com.fasterxml.jackson.core.BaseTest
+{
+    private final JsonFactory F = new JsonFactory();
+
+    public void testGetNumberTypeFPDefault() throws Exception {
+        // Test that UNKNOWN is returned for non-floating-point values
+        String json = "123";
+        JsonParser p = createParser(json);
+        assertToken(p.nextToken(), JsonToken.VALUE_NUMBER_INT);
+        assertEquals(JsonParser.NumberTypeFP.UNKNOWN, p.getNumberTypeFP());
+        p.close();
+    }
+
+    public void testGetNumberTypeFPForDouble() throws Exception {
+        String json = "3.14159";
+        JsonParser p = createParser(json);
+        assertToken(p.nextToken(), JsonToken.VALUE_NUMBER_FLOAT);
+        // Default JSON parsing returns DOUBLE64 for regular floats
+        assertEquals(JsonParser.NumberTypeFP.DOUBLE64, p.getNumberTypeFP());
+        p.close();
+    }
+
+    public void testGetNumberTypeFPForBigDecimal() throws Exception {
+        String json = "3.141592653589793238462643383279";
+        JsonParser p = createParserUsingReader(json);
+        assertToken(p.nextToken(), JsonToken.VALUE_NUMBER_FLOAT);
+        // Long decimals should be parsed as BigDecimal
+        assertEquals(JsonParser.NumberTypeFP.BIG_DECIMAL, p.getNumberTypeFP());
+        p.close();
+    }
+
+    public void testGetNumberTypeFPScientificNotation() throws Exception {
+        String json = "1.23e10";
+        JsonParser p = createParser(json);
+        assertToken(p.nextToken(), JsonToken.VALUE_NUMBER_FLOAT);
+        assertEquals(JsonParser.NumberTypeFP.DOUBLE64, p.getNumberTypeFP());
+        p.close();
+    }
+
+    public void testGetNumberTypeFPForInteger() throws Exception {
+        String json = "42";
+        JsonParser p = createParser(json);
+        assertToken(p.nextToken(), JsonToken.VALUE_NUMBER_INT);
+        assertEquals(JsonParser.NumberTypeFP.UNKNOWN, p.getNumberTypeFP());
+        p.close();
+    }
+
+    public void testGetNumberTypeFPForNegativeNumber() throws Exception {
+        String json = "-2.5";
+        JsonParser p = createParser(json);
+        assertToken(p.nextToken(), JsonToken.VALUE_NUMBER_FLOAT);
+        assertEquals(JsonParser.NumberTypeFP.DOUBLE64, p.getNumberTypeFP());
+        p.close();
+    }
+
+    public void testGetNumberTypeFPForZero() throws Exception {
+        String json = "0.0";
+        JsonParser p = createParser(json);
+        assertToken(p.nextToken(), JsonToken.VALUE_NUMBER_FLOAT);
+        assertEquals(JsonParser.NumberTypeFP.DOUBLE64, p.getNumberTypeFP());
+        p.close();
+    }
+
+    private JsonParser createParser(String json) throws Exception {
+        return F.createParser(json.getBytes("UTF-8"));
+    }
+
+    private JsonParser createParserUsingReader(String json) throws Exception {
+        return F.createParser(json);
+    }
+}

