+import java.io.IOException;
+import java.nio.file.*;
+import java.util.HashSet;
+import java.util.Set;
+
+/**
+ * Tracks DLQ segment metadata and monitors for deleted segments.
+ * This class watches for .deleted_segment notification files created by the reader
+ * when clean_consumed is used, and updates the queue size metric accordingly.
+ */
+public class DLQSegmentMetadataTracker {
+    private final Path queuePath;
+    private final Set<Path> processedDeletions;
+    private long totalQueueSizeInBytes;
+
+    public DLQSegmentMetadataTracker(Path queuePath) {
+        this.queuePath = queuePath;
+        this.processedDeletions = new HashSet<>();
+        recalculateQueueSize();
+    }
+
+    /**
+     * Checks for any new .deleted_segment files and updates the queue size accordingly.
+     */
+    public void checkForDeletedSegments() {
+        try (DirectoryStream<Path> stream = Files.newDirectoryStream(queuePath, "*.deleted_segment")) {
+            for (Path deletedMarker : stream) {
+                if (!processedDeletions.contains(deletedMarker)) {
+                    processDeletedSegment(deletedMarker);
+                    processedDeletions.add(deletedMarker);
+                }
+            }
+        } catch (NoSuchFileException e) {
+            // Queue directory doesn't exist yet
+        } catch (IOException e) {
+            // Log error but continue - we'll recalculate on next call
+        }
+    }
+
+    private void processDeletedSegment(Path deletedMarker) {
+        try {
+            // Extract the original segment name from the deleted marker
+            String segmentName = deletedMarker.getFileName().toString()
+                    .replace(".deleted_segment", "");
+            Path segmentPath = deletedMarker.getParent().resolve(segmentName);
+
+            // If segment still exists, it's being deleted - calculate its size
+            if (Files.exists(segmentPath)) {
+                totalQueueSizeInBytes -= calculateSegmentSize(segmentPath);
+            }
+
+            // Clean up the marker file
+            Files.deleteIfExists(deletedMarker);
+        } catch (IOException e) {
+            // Log error but continue
+        }
+    }
+
+    private long calculateSegmentSize(Path segmentPath) throws IOException {
+        long size = 0;
+        if (Files.exists(segmentPath)) {
+            try (DirectoryStream<Path> stream = Files.newDirectoryStream(segmentPath)) {
+                for (Path entry : stream) {
+                    size += Files.size(entry);
+                }
+            }
+        }
+        return size;
+    }
+
+    /**
+     * Recalculates the total queue size by scanning the filesystem.
+     */
+    public void recalculateQueueSize() {
+        totalQueueSizeInBytes = 0;
+        try (DirectoryStream<Path> stream = Files.newDirectoryStream(queuePath, "*.seg")) {
+            for (Path segmentPath : stream) {
+                totalQueueSizeInBytes += calculateSegmentSize(segmentPath);
+            }
+        } catch (NoSuchFileException e) {
+            // Queue directory doesn't exist yet
+        } catch (IOException e) {
+            // Log error but continue with 0
+        }
+    }
+
+    /**
+     * Returns the total queue size in bytes.
+     * @return the total size of all segments in the queue
+     */
+    public long getTotalQueueSizeInBytes() {
+        return totalQueueSizeInBytes;
+    }
+}
