@@ -0,0 +1,52 @@
+package org.logstash.log;
+
+import java.util.HashMap;
+import java.util.Map;
+
+/**
+ * Utility class to fix duplicate field names in JSON objects.
+ * When JSON logging encounters multiple fields with the same name,
+ * this class renames subsequent occurrences by appending a suffix.
+ */
+public final class JsonFixer {
+
+    private JsonFixer() {
+        // Utility class
+    }
+
+    /**
+     * Fixes duplicate field names in a map by appending "_1" suffix to subsequent occurrences.
+     * Only fields matching the original field name pattern get renamed.
+     *
+     * @param map the map to fix
+     * @param fieldName the field name to check for duplicates
+     * @return a new map with duplicate fields renamed
+     */
+    public static Map<String, Object> fixDuplicateFields(Map<String, Object> map, String fieldName) {
+        if (map == null || fieldName == null) {
+            return map;
+        }
+
+        Map<String, Object> result = new HashMap<>(map);
+        int counter = 1;
+        String currentFieldName = fieldName;
+
+        while (result.containsKey(currentFieldName)) {
+            counter++;
+            currentFieldName = fieldName + Loggable.MESSAGE_FIELD_SUFFIX;
+            // Keep incrementing the suffix number until we find an available key
+            while (result.containsKey(currentFieldName)) {
+                currentFieldName = fieldName + "_" + counter;
+                counter++;
+            }
+            if (map.containsKey(fieldName)) {
+                Object value = result.remove(fieldName);
+                result.put(currentFieldName, value);
+            }
+        }
+
+        return result;
+    }
+}
