+/**
+ * Utility class to handle Netty's maxOrder configuration.
+ * In Netty 4.1.75, the default maxOrder was changed from 11 to 9.
+ * This class ensures the maxOrder is set to 11 to maintain performance
+ * for messages larger than 2KB.
+ */
+public final class NettyMaxOrderUtil {
+    
+    private static final String MAX_ORDER_PROPERTY = "-Dio.netty.allocator.maxOrder=11";
+    private static final String MAX_ORDER_FLAG = "-Dio.netty.allocator.maxOrder";
+    
+    private NettyMaxOrderUtil() {
+        // Utility class
+    }
+    
+    /**
+     * Ensures the Netty maxOrder property is set to 11 if not already present.
+     * @param jvmOptions the list of JVM options to check and potentially modify
+     */
+    public static void ensureMaxOrderProperty(final List<String> jvmOptions) {
+        if (jvmOptions.stream().noneMatch(opt -> opt.startsWith(MAX_ORDER_FLAG))) {
+            jvmOptions.add(MAX_ORDER_PROPERTY);
+        }
+    }
+}
