+     * @param name the name of this flow metric
+     * @param numeratorMetric the metric providing the numerator (event count)
+     * @param denominatorMetric the metric providing the denominator (typically time/uptime)
+     * @param precision the number of significant figures for rounding
+     */
+    protected BaseFlowMetric(final String name, final Metric<T> numeratorMetric, 
+                             final Metric<T> denominatorMetric, final int precision) {
+        this.name = Objects.requireNonNull(name, "name cannot be null");
+        this.numeratorMetric = Objects.requireNonNull(numeratorMetric, "numeratorMetric cannot be null");
+        this.denominatorMetric = Objects.requireNonNull(denominatorMetric, "denominatorMetric cannot be null");
+        this.precision = precision > 0 ? precision : 3;
+        this.lastCapture = new AtomicReference<>();
+        this.sequence = new AtomicLong(0);
+    }
+
+    /**
+     * Creates a new BaseFlowMetric with default precision of 3 significant figures.
+     *
+     * @param name the name of this flow metric
+     * @param numeratorMetric the metric providing the numerator (event count)
+     * @param denominatorMetric the metric providing the denominator (typically time/uptime)
+     */
+    protected BaseFlowMetric(final String name, final Metric<T> numeratorMetric, 
+                             final Metric<T> denominatorMetric) {
+        this(name, numeratorMetric, denominatorMetric, 3);
+    }
+
+    @Override
+    public String getName() {
