+        if (current == null || capture.getCaptureTimeNanos() > current.getCaptureTimeNanos()) {
+            lastCapture.set(capture);
+        }
+    }
+
+    @Override
+    public Double getValue() {
+        return getValue(System.nanoTime());
+    }
+
+    /**
+     * Gets the flow rate value calculated at the specified time.
+     *
+     * @param nanoTime the time in nanoseconds for the calculation
+     * @return the calculated flow rate, or null if insufficient data
+     */
+    public Double getValue(final long nanoTime) {
+        final FlowCapture capture = lastCapture.get();
+        if (capture == null) {
+            return null;
+        }
+        return calculateRate(capture, nanoTime);
+    }
+
+    /**
+     * Calculates the rate of change between captures.
+     *
+     * @param capture the capture to calculate rate for
+     * @param currentTimeNanos the current time in nanoseconds
+     * @return the calculated rate rounded to the configured precision
+     */
+    protected Double calculateRate(final FlowCapture capture, final long currentTimeNanos) {
+        final double numerator = capture.getNumeratorValue().doubleValue();
+        final double denominator = capture.getDenominatorValue().doubleValue();
+        
+        if (denominator <= 0) {
+            return null;
+        }
+        
+        final double rate = numerator / denominator;
+        return roundToPrecision(rate, precision);
+    }
+
+    /**
+     * Rounds a value to the specified number of significant figures.
+     *
+     * @param value the value to round
+     * @param significantFigures the number of significant figures
+     * @return the rounded value
+     */
+    protected static Double roundToPrecision(final double value, final int significantFigures) {
+        if (value == 0) {
+            return 0.0;
+        }
+        
+        if (!Double.isFinite(value)) {
+            return value;
+        }
+        
+        final double magnitude = Math.floor(Math.log10(Math.abs(value)));
+        final double scale = Math.pow(10, magnitude - significantFigures + 1);
+        final double scaled = value / scale;
+        final double rounded = Math.round(scaled);
+        
+        return rounded * scale;
+    }
+
+    /**
+     * Gets the last capture for testing purposes.
+     *
+     * @return the last capture, or null if none
+     */
+    protected FlowCapture getLastCapture() {
+        return lastCapture.get();
+    }
+
+    @Override
+    public String toString() {
+        return "BaseFlowMetric{" +
+                "name='" + name + '\'' +
+                ", value=" + getValue() +
+                '}';
+    }
+}

