+public final class ReceiveResponse {
+
+    private final boolean success;
+    private final int sequencePosition;
+    private final Exception exception;
+    private final boolean closing;
+
+    private ReceiveResponse(boolean success, int sequencePosition, Exception exception, boolean closing) {
