+        this.sequencePosition = sequencePosition;
+        this.exception = exception;
+        this.closing = closing;
+    }
+
+    /**
+     * Creates a response representing a successful receive operation.
+     * @return a completed ReceiveResponse
+     */
+    public static ReceiveResponse completed() {
+        return new ReceiveResponse(true, -1, null, false);
+    }
+
+    /**
+     * Creates a response representing a failed receive operation at a given sequence position
+     * with an associated exception.
+     * @param sequencePosition the position in the batch where the failure occurred
+     * @param exception the exception that caused the failure
+     * @return a failed ReceiveResponse
+     */
+    public static ReceiveResponse failedAt(int sequencePosition, Exception exception) {
+        return new ReceiveResponse(false, sequencePosition, exception, false);
+    }
+
+    /**
+     * Creates a response representing a pipeline input that is closing.
+     * @return a closing ReceiveResponse
+     */
+    public static ReceiveResponse closing() {
+        return new ReceiveResponse(false, -1, null, true);
+    }
+
+    public boolean isSuccess() {
+        return success;
+    }
+
+    public int getSequencePosition() {
+        return sequencePosition;
+    }
+
+    public Exception getException() {
+        return exception;
+    }
+
+    public boolean isClosing() {
