+
+package org.logstash.util;
+
+import java.util.concurrent.ThreadLocalRandom;
+
+/**
+ * Implements a customizable retry mechanism with exponential delay logic,
+ * designed to execute retryable actions and handle transient failures up to
+ * a configurable maximum number of attempts.
+ */
+public class ExponentialBackoff {
+    private static final long MAX_INTERVAL_MS = 30_000;
+    private final int maxAttempts;
+    private final long baseIntervalMillis;
+    private final long intervalRangeMillis;
+
+    public ExponentialBackoff(long baseIntervalMillis, long intervalRangeMillis, int maxAttempts) {
+        this.baseIntervalMillis = baseIntervalMillis;
+        this.intervalRangeMillis = intervalRangeMillis;
+        this.maxAttempts = maxAttempts;
+    }
+
+    /**
+     * Executes the given operation with automatic retries using exponential backoff.
+     * @param action the operation to execute
+     * @param <T> the return type of the operation
+     * @return the result of the operation
+     * @throws RetryException if all retry attempts fail
+     */
+    public <T> T retryable(CheckedSupplier<T> action) {
+        Exception cause = null;
+        for (int attempt = 0; attempt < maxAttempts; attempt++) {
+            try {
+                return action.get();
+            } catch (Exception e) {
+                cause = e;
+                if (attempt < maxAttempts - 1) {
+                    try {
+                        Thread.sleep(calculateSleepTime(attempt));
+                    } catch (InterruptedException ie) {
+                        Thread.currentThread().interrupt();
+                        throw new RetryException("Retry interrupted", ie);
+                    }
+                }
+            }
+        }
+        throw new RetryException("All attempts failed", cause);
+    }
+
+    private long calculateSleepTime(int attempt) {
+        long intervalRange = Math.min(
+            (long) (baseIntervalMillis * Math.pow(2, attempt)),
+            MAX_INTERVAL_MS
+        );
+        return ThreadLocalRandom.current().nextLong(intervalRange) + baseIntervalMillis;
+    }
+
+    public static void main(String[] args) throws Exception {
+        ExponentialBackoff backoff = new ExponentialBackoff(100, 50, 5);
+        int[] count = {0};
+
+        String result = backoff.retryable(() -> {
+            count[0]++;
+            if (count[0] < 3) {
+                throw new RuntimeException("Attempt " + count[0] + " failed");
+            }
+            return "Success on attempt " + count[0];
+        });
+
+        System.out.println(result);
+    }
+}

