+ *     http://www.apache.org/licenses/LICENSE-2.0
+ */
+package org.logstash.util;
+
+public class ExponentialBackoff {
+    private final long baseIntervalMillis;
+    private final long maxIntervalMillis;
+    private final int maxRetries;
+
+    public ExponentialBackoff(long baseIntervalMillis, long maxIntervalMillis, int maxRetries) {
+        this.baseIntervalMillis = baseIntervalMillis;
+        this.maxIntervalMillis = maxIntervalMillis;
+        this.maxRetries = maxRetries;
+    }
+
+    public <T> T execute(CheckedSupplier<T> action) throws RetryException {
+        Exception lastException = null;
+        long interval = baseIntervalMillis;
+
+        for (int attempt = 0; attempt <= maxRetries; attempt++) {
+            try {
+                return action.get();
+            } catch (Exception e) {
+                lastException = e;
+                if (attempt < maxRetries) {
+                    try {
+                        Thread.sleep(interval);
+                    } catch (InterruptedException ie) {
+                        Thread.currentThread().interrupt();
+                        throw new RetryException("Retry interrupted", ie);
+                    }
+                    interval = Math.min(interval * 2, maxIntervalMillis);
+                }
+            }
+        }
+        throw new RetryException("Max retries exceeded", lastException);
+    }
+}
