index 0000000..1234567
--- /dev/null
+++ b/src/main/java/com/fasterxml/jackson/databind/introspect/PotentialCreator.java
@@ -0,0 +1,183 @@
+package com.fasterxml.jackson.databind.introspect;
+
+import java.lang.reflect.Constructor;
+import java.lang.reflect.Member;
+import java.lang.reflect.Method;
+
+import com.fasterxml.jackson.databind.cfg CreatorProperties;
+
+/**
+ * Abstraction for representing a "potential" creator - a constructor or
+ * factory method that could serve as the primary creator for deserializing
+ * a class.
+ *<p>
+ * This class is used as the return type for {@link AnnotationIntrospector#findPrimaryCreator}
+ * to allow custom introspectors (like the Kotlin module) to indicate which
+ * creator should be used when no explicit annotations are present.
+ *
+ * @since 2.16
+ */
+public class PotentialCreator {
+
+    /**
+     * Enumeration of the type of creator.
+     */
+    public enum CreatorType {
+        /** Creator is a constructor */
+        CONSTRUCTOR,
+        /** Creator is a static factory method */
+        FACTORY
+    }
+
+    private final CreatorType creatorType;
+    private final Member member;
+    private final CreatorProperties mode;
+    private final int delegateIndex;
+    private final int delegateParameterIndex;
+
+    private PotentialCreator(CreatorType creatorType, Member member,
+            CreatorProperties mode, int delegateIndex, int delegateParameterIndex) {
+        this.creatorType = creatorType;
+        this.member = member;
+        this.mode = mode;
+        this.delegateIndex = delegateIndex;
+        this.delegateParameterIndex = delegateParameterIndex;
+    }
+
+    /**
+     * Factory method for creating a potential creator from a constructor.
+     */
+    public static PotentialCreator constructor(Constructor<?> constructor) {
+        return new PotentialCreator(CreatorType.CONSTRUCTOR, constructor,
+                CreatorProperties.DEFAULT, -1, -1);
+    }
+
+    /**
+     * Factory method for creating a potential creator from a constructor
+     * with explicit mode setting.
+     */
+    public static PotentialCreator constructor(Constructor<?> constructor,
+            CreatorProperties mode) {
+        return new PotentialCreator(CreatorType.CONSTRUCTOR, constructor,
+                mode, -1, -1);
+    }
+
+    /**
+     * Factory method for creating a potential creator from a factory method.
+     */
+    public static PotentialCreator factory(Method factoryMethod) {
+        return new PotentialCreator(CreatorType.FACTORY, factoryMethod,
+                CreatorProperties.DEFAULT, -1, -1);
+    }
+
+    /**
+     * Factory method for creating a potential creator from a factory method
+     * with explicit mode setting.
+     */
+    public static PotentialCreator factory(Method factoryMethod,
+            CreatorProperties mode) {
+        return new PotentialCreator(CreatorType.FACTORY, factoryMethod,
+                mode, -1, -1);
+    }
+
+    /**
+     * Returns the type of this creator.
+     */
+    public CreatorType getCreatorType() {
+        return creatorType;
+    }
+
+    /**
+     * Returns the underlying member (constructor or method) for this creator.
+     */
+    public Member getMember() {
+        return member;
+    }
+
+    /**
+     * Returns the creator mode to use.
+     */
+    public CreatorProperties getMode() {
+        return mode;
+    }
+
+    /**
+     * Returns the index of the delegate parameter for DELEGATING mode,
+     * or -1 if not applicable.
+     */
+    public int getDelegateIndex() {
+        return delegateIndex;
+    }
+
+    /**
+     * Returns the index of the delegate parameter,
+     * or -1 if not applicable.
+     */
+    public int getDelegateParameterIndex() {
+        return delegateParameterIndex;
+    }
+
+    /**
+     * Returns the constructor if this is a constructor-based creator,
+     * or null otherwise.
+     */
+    public Constructor<?> getConstructor() {
+        if (creatorType == CreatorType.CONSTRUCTOR) {
+            return (Constructor<?>) member;
+        }
+        return null;
+    }
+
+    /**
+     * Returns the factory method if this is a factory-based creator,
+     * or null otherwise.
+     */
+    public Method getFactory() {
+        if (creatorType == CreatorType.FACTORY) {
+            return (Method) member;
+        }
+        return null;
+    }
+
+    /**
+     * Returns true if this creator is based on a constructor.
+     */
+    public boolean isConstructor() {
+        return creatorType == CreatorType.CONSTRUCTOR;
+    }
+
+    /**
+     * Returns true if this creator is based on a factory method.
+     */
+    public boolean isFactory() {
+        return creatorType == CreatorType.FACTORY;
+    }
+
+    @Override
+    public String toString() {
+        return "PotentialCreator{" +
+                "creatorType=" + creatorType +
+                ", member=" + member +
+                ", mode=" + mode +
+                '}';
+    }
+}
