+package com.fasterxml.jackson.databind.deser.filter;
+
+import java.util.*;
+
+import com.fasterxml.jackson.annotation.JsonIgnore;
+import com.fasterxml.jackson.annotation.JsonIgnoreProperties;
+
+import com.fasterxml.jackson.databind.*;
+import com.fasterxml.jackson.databind.json.JsonMapper;
+
+/**
+ * Test for [databind#3948]: ensure that {@code @JsonIgnore} annotation
+ * works correctly for transient fields.
+ */
+public class Issue3948Test extends BaseMapTest
+{
+    // Test class with transient field that has @JsonIgnore
+    static class TransientWithJsonIgnore {
+        public String normalField = "normal";
+
+        @JsonIgnore
+        transient String ignoredTransient = "should be ignored";
+
+        public String anotherNormal = "another";
+    }
+
+    // Test class with transient field that does NOT have @JsonIgnore
+    static class TransientWithoutJsonIgnore {
+        public String normalField = "normal";
+
+        transient String justTransient = "just transient";
+
+        public String anotherNormal = "another";
+    }
+
+    // Test class with transient backing field for property
+    static class TransientBackingFieldWithJsonIgnore {
+        private String _name;
+
+        public String getName() { return _name; }
+        public void setName(String n) { _name = n; }
+
+        @JsonIgnore
+        transient String _ignoredBacking;
+    }
+
+    // Test class with @JsonIgnoreProperties on class
+    @JsonIgnoreProperties("transientField")
+    static class ClassLevelIgnoreTransient {
+        public String normalField = "normal";
+
+        transient String transientField = "should be ignored via class-level";
+
+        public String anotherNormal = "another";
+    }
+
+    private final ObjectMapper MAPPER = newJsonMapper();
+
+    /**
+     * Test that transient field with @JsonIgnore is properly ignored
+     */
+    public void testTransientFieldWithJsonIgnore() throws Exception
+    {
+        TransientWithJsonIgnore value = new TransientWithJsonIgnore();
+        String json = MAPPER.writeValueAsString(value);
+
+        // Should NOT contain ignoredTransient
+        assertFalse("JSON should not contain 'ignoredTransient' but was: " + json,
+                json.contains("ignoredTransient"));
+        assertFalse("JSON should not contain 'should be ignored' but was: " + json,
+                json.contains("should be ignored"));
+
+        // Should contain normal fields
+        assertTrue("JSON should contain 'normalField' but was: " + json,
+                json.contains("normalField"));
+        assertTrue("JSON should contain 'anotherNormal' but was: " + json,
+                json.contains("anotherNormal"));
+    }
+
+    /**
+     * Test that transient field without @JsonIgnore is still ignored
+     */
+    public void testTransientFieldWithoutJsonIgnore() throws Exception
+    {
+        TransientWithoutJsonIgnore value = new TransientWithoutJsonIgnore();
+        String json = MAPPER.writeValueAsString(value);
+
+        // Should NOT contain justTransient
+        assertFalse("JSON should not contain 'justTransient' but was: " + json,
+                json.contains("justTransient"));
+        assertFalse("JSON should not contain 'just transient' but was: " + json,
+                json.contains("just transient"));
+
+        // Should contain normal fields
+        assertTrue("JSON should contain 'normalField' but was: " + json,
+                json.contains("normalField"));
+    }
+
+    /**
+     * Test that transient backing field with @JsonIgnore is properly ignored
+     */
+    public void testTransientBackingFieldWithJsonIgnore() throws Exception
+    {
+        TransientBackingFieldWithJsonIgnore value = new TransientBackingFieldWithJsonIgnore();
+        value.setName("test");
+
+        String json = MAPPER.writeValueAsString(value);
+
+        // Should NOT contain _ignoredBacking
+        assertFalse("JSON should not contain '_ignoredBacking' but was: " + json,
+                json.contains("_ignoredBacking"));
+
+        // Should contain 'name' property
+        assertTrue("JSON should contain 'name' but was: " + json,
+                json.contains("name"));
+    }
+
+    /**
+     * Test that @JsonIgnoreProperties on class level works with transient fields
+     */
+    public void testClassLevelIgnoreTransient() throws Exception
+    {
+        ClassLevelIgnoreTransient value = new ClassLevelIgnoreTransient();
+        String json = MAPPER.writeValueAsString(value);
+
+        // Should NOT contain transientField
+        assertFalse("JSON should not contain 'transientField' but was: " + json,
+                json.contains("transientField"));
+
+        // Should contain normal fields
+        assertTrue("JSON should contain 'normalField' but was: " + json,
+                json.contains("normalField"));
+    }
+
+    /**
+     * Test deserialization as well - ensure transient fields are not included
+     */
+    public void testTransientFieldNotDeserialized() throws Exception
+    {
+        String json = "{\"normalField\":\"value1\",\"ignoredTransient\":\"shouldNotAppear\",\"anotherNormal\":\"value2\"}";
+
+        TransientWithJsonIgnore value = MAPPER.readValue(json, TransientWithJsonIgnore.class);
+
+        assertEquals("value1", value.normalField);
+        assertEquals("another", value.anotherNormal);
+        // The transient field should have default value, not the JSON value
+        assertEquals("should be ignored", value.ignoredTransient);
+    }
+}

