+/*
+ * Copyright (c) 2017 Mockito contributors
+ */
+package org.mockito.junit.jupiter.resolver;
+
+import static org.mockito.internal.util.ConsoleLogger.of;
+
+import java.lang.reflect.Parameter;
+import java.lang.reflect.ParameterizedType;
+import java.lang.reflect.Type;
+
+import org.junit.jupiter.api.extension.ParameterContext;
+import org.junit.jupiter.api.extension.ParameterResolutionException;
+import org.junit.jupiter.api.extension.ParameterResolver;
+import org.mockito.Captor;
+import org.mockito.ArgumentCaptor;
+import org.mockito.internal.util.ConsoleLogger;
+
+/**
+ * A JUnit 5 {@link ParameterResolver} which can resolve parameters annotated with {@link Captor}.
+ *
+ * <p>This resolver creates and initializes {@link ArgumentCaptor} instances for method parameters
+ * that are annotated with {@link Captor}, allowing for type-safe argument capture in tests.
+ *
+ * @since 4.6.0
+ */
+public class CaptorParameterResolver implements ParameterResolver {
+
+    private final ConsoleLogger logger;
+
+    /**
+     * Creates a new {@link CaptorParameterResolver}.
+     */
+    public CaptorParameterResolver() {
+        this(of());
+    }
+
+    /**
+     * Creates a new {@link CaptorParameterResolver} with a custom logger.
+     *
+     * @param logger the logger to use
+     */
+    CaptorParameterResolver(ConsoleLogger logger) {
+        this.logger = logger;
+    }
+
+    @Override
+    @SuppressWarnings("unchecked")
+    public Object resolveParameter(ParameterContext parameterContext) {
+        Parameter parameter = parameterContext.getParameter();
+        Class<?> parameterType = parameter.getType();
+        Type genericType = parameter.getParameterizedizedType();
+
+        logger.log(String.format("Resolving @Captor parameter '%s' of type '%s'",
+                parameter.getName(), genericType));
+
+        return ArgumentCaptor.forClass((Class<Object>) extractCaptorType(parameter, genericType));
+    }
+
+    @Override
+    public boolean supports(ParameterContext parameterContext) {
+        return parameterContext.getParameter().isAnnotationPresent(Captor.class);
+    }
+
+    private Class<?> extractCaptorType(Parameter parameter, Type genericType) {
+        if (genericType instanceof Class) {
+            return (Class<?>) genericType;
+        } else if (genericType instanceof ParameterizedType) {
+            ParameterizedType parameterizedType = (ParameterizedType) genericType;
+            Type[] typeArguments = parameterizedType.getActualTypeArguments();
+            if (typeArguments.length == 1) {
+                if (typeArguments[0] instanceof Class) {
+                    return (Class<?>) typeArguments[0];
+                }
+            }
+        }
+        throw new ParameterResolutionException(
+                "Unable to resolve captor type for parameter '" + parameter.getName() + "'");
+    }
+}
