+/*
+ * Copyright (c) 2017 Mockito contributors
+ */
+package org.mockito.junit.jupiter.resolver;
+
+import static java.util.Arrays.asList;
+
+import java.util.List;
+
+import org.junit.jupiter.api.extension.ParameterContext;
+import org.junit.jupiter.api.extension.ParameterResolutionException;
+import org.junit.jupiter.api.extension.ParameterResolver;
+
+/**
+ * A composite {@link ParameterResolver} that tries to resolve parameters using a list of
+ * registered resolvers.
+ *
+ * <p>The resolvers are tried in order, and the first one that supports a parameter is used
+ * to resolve it.
+ *
+ * @since 4.6.0
+ */
+public class CompositeParameterResolver implements ParameterResolver {
+
+    private final List<ParameterResolver> resolvers;
+
+    /**
+     * Creates a new {@link CompositeParameterResolver} with the given resolvers.
+     *
+     * @param resolvers the resolvers to use
+     */
+    @SafeVarargs
+    public CompositeParameterResolver(ParameterResolver... resolvers) {
+        this(asList(resolvers));
+    }
+
+    /**
+     * Creates a new {@link CompositeParameterResolver} with the given list of resolvers.
+     *
+     * @param resolvers the list of resolvers to use
+     */
+    public CompositeParameterResolver(List<ParameterResolver> resolvers) {
+        this.resolvers = resolvers;
+    }
+
+    @Override
+    public boolean supports(ParameterContext parameterContext) {
+        return resolvers.stream().anyMatch(resolver -> resolver.supports(parameterContext));
+    }
+
+    @Override
+    public Object resolveParameter(ParameterContext parameterContext) {
+        return resolvers.stream()
+                .filter(resolver -> resolver.supports(parameterContext))
+                .findFirst()
+                .orElseThrow(() -> new ParameterResolutionException(
+                        "No ParameterResolver registered for parameter"))
+                .resolveParameter(parameterContext);
+    }
+}
