+  ordinal: (n) => `${n}.`,
+  formats: {
+    full: "y. MMMM d., dddd",
+    long: "y. MMMM d.",
+    medium: "y. MMM d.",
+    short: "y. MMM d.",
+  },
+  relativeTime: {
+    future: " {0}",
+    past: " {0}",
+    s: "néhány másodperc",
+    ss: "{0} másodperc",
+    m: "egy perc",
+    mm: "{0} perc",
+    h: "egy óra",
+    hh: "{0} óra",
+    d: "egy nap",
+    dd: "{0} nap",
+    M: "egy hónap",
+    MM: "{0} hónap",
+    y: "egy év",
+    yy: "{0} év",
+  },
+  timeGetters: {
+    date: (d) => d.getDate(),
+    month: (d) => d.getMonth(),
+    year: (d) => d.getFullYear(),
+    hour: (d) => d.getHours(),
+    minute: (d) => d.getMinutes(),
+    second: (d) => d.getSeconds(),
+    weekday: (d) => d.getDay(),
+  },
+  formats: {
+    ...Locale.prototype.formats,
+  },
+};
+
+/**
+ * Hungarian relative time formatter
+ * Handles the special Hungarian suffixes for past and future times
+ */
+export function formatRelativeTimeHU(
+  value: number,
+  unit: "year" | "month" | "day" | "hour" | "minute" | "second",
+  isPast: boolean
+): string {
+  const suffixes: Record<string, { past: string; future: string }> = {
+    year: { past: "éve", future: "év múlva" },
+    month: { past: "hónapja", future: "hónap múlva" },
+    day: { past: "napja", future: "nap múlva" },
+    hour: { past: "órája", future: "óra múlva" },
+    minute: { past: "perce", future: "perc múlva" },
+    second: { past: "másodperce", future: "másodperc múlva" },
+  };
+
+  const suffix = suffixes[unit];
+  if (!suffix) return "";
+
+  if (value === 1) {
+    // Handle singular forms
+    if (unit === "year") {
+      return isPast ? "egy éve" : "egy év múlva";
+    }
+    if (unit === "month") {
+      return isPast ? "egy hónapja" : "egy hónap múlva";
+    }
+    if (unit === "day") {
+      return isPast ? "egy napja" : "egy nap múlva";
+    }
+    if (unit === "hour") {
+      return isPast ? "egy órája" : "egy óra múlva";
+    }
+    if (unit === "minute") {
+      return isPast ? "egy perce" : "egy perc múlva";
+    }
+    if (unit === "second") {
+      return isPast ? "egy másodperce" : "egy másodperc múlva";
+    }
+  }
+
+  const suffixText = isPast ? suffix.past : suffix.future;
+  return `${value} ${suffixText}`;
+}
