diff --git a/packages/svelte/tests/parser-loose.test.ts b/packages/svelte/tests/parser-loose.test.ts
new file mode 100644
index 0000000..1234567
--- /dev/null
+++ b/packages/svelte/tests/parser-loose.test.ts
@@ -0,0 +1,87 @@
+import { test } from 'vitest';
+import { parse } from '../src/compiler/phases/parse/index.js';
+
+test('loose mode: incomplete element tag', (t) => {
+	const source = `<Co`;
+	const result = parse(source, { loose: true });
+	
+	// Should not throw, should return a partial parse result
+	expect(result).toBeDefined();
+	expect(result.fragment).toBeDefined();
+});
+
+test('loose mode: incomplete element with partial attributes', (t) => {
+	const source = `<Comp attr`;
+	const result = parse(source, { loose: true });
+	
+	expect(result).toBeDefined();
+	expect(result.fragment).toBeDefined();
+});
+
+test('loose mode: unclosed script tag', (t) => {
+	const source = `<script>
+   import Comp from './comp.svelte'
+</script
+<Co`;
+	const result = parse(source, { loose: true });
+	
+	expect(result).toBeDefined();
+	expect(result.fragment).toBeDefined();
+});
+
+test('loose mode: self-closing incomplete tag', (t) => {
+	const source = `<Comp /`;
+	const result = parse(source, { loose: true });
+	
+	expect(result).toBeDefined();
+});
+
+test('loose mode: incomplete attribute value', (t) => {
+	const source = `<Comp attr="`;
+	const result = parse(source, { loose: true });
+	
+	expect(result).toBeDefined();
+});
+
+test('strict mode: same inputs should still error', (t) => {
+	const source = `<Co`;
+	
+	expect(() => parse(source, { loose: false })).toThrow();
+});
+
+test('loose mode: valid code still parses correctly', (t) => {
+	const source = `<script>
+	import Comp from './comp.svelte';
+</script>
+<Comp />`;
+	
+	const result = parse(source, { loose: true });
+	
+	expect(result).toBeDefined();
+	expect(result.fragment.nodes.length).toBeGreaterThan(0);
+});
+
+test('loose mode: nested incomplete elements', (t) => {
+	const source = `<div>
+	<Co
+	<span
+</div>`;
+	
+	const result = parse(source, { loose: true });
+	
+	expect(result).toBeDefined();
+});
+
+test('loose mode: incomplete mustache expression', (t) => {
+	const source = `<div>{`;
+	const result = parse(source, { loose: true });
+	
+	expect(result).toBeDefined();
+});
+
+test('loose mode: incomplete comment', (t) => {
+	const source = `<!--`;
+	const result = parse(source, { loose: true });
+	
+	expect(result).toBeDefined();
+});
